import{at as e,it as t,t as n,vt as r}from"./chunks/framework.DkAysg6d.js";var i=JSON.parse(`{"title":"Matrix","description":"","frontmatter":{},"headers":[],"relativePath":"showcase-matrix.md","filePath":"pages/showcase-matrix.md"}`),a={name:`showcase-matrix.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="matrix" tabindex="-1">Matrix <a class="header-anchor" href="#matrix" aria-label="Permalink to “Matrix”">​</a></h1><p>Eight regions by seven columns with the orientation transposed, live, and a span of two by three becoming three by two as it flips.</p><p><a href="./demo/matrix" target="_blank" rel="noreferrer">Open the route full screen</a></p><h2 id="what-it-is-stressing" tabindex="-1">What it is stressing <a class="header-anchor" href="#what-it-is-stressing" aria-label="Permalink to “What it is stressing”">​</a></h2><p><code>state.orientation</code> set to columns, which is the layout whose first column holds what are normally column headers. Pinning, resizing, sorting, and spanning all run inside the transposed frame.</p><h2 id="the-span-flipped" tabindex="-1">The span, flipped <a class="header-anchor" href="#the-span-flipped" aria-label="Permalink to “The span, flipped”">​</a></h2><p>A cell declaring two rows by three columns has to occupy three rows by two columns once the axes swap. <code>neutralSpan</code> in <code>src/12_transpose.ts</code> crosses the declaration into a vertical count and a horizontal count, and <code>coveredBy</code> in the same file recomputes which cells the span now hides.</p><p>Watching the covered set swap is the clearest demonstration that the transpose reaches the model rather than the stylesheet.</p><h2 id="the-workaround-it-carries" tabindex="-1">The workaround it carries <a class="header-anchor" href="#the-workaround-it-carries" aria-label="Permalink to “The workaround it carries”">​</a></h2><p>A cell reads its value out of the row axis&#39;s own map, and under a transposed orientation the vertical key is a column id, which owns no row value. <code>demo/3_matrix.ts</code> therefore rewrites the transposed header band after each pass and supplies its own cell content.</p><p>Copy that shape until the renderer crosses the seats itself. The state of the two halves is on <a href="/hafley-rxjs/signal-grid/why-seats">The seat table</a>.</p><h2 id="features-it-exercises" tabindex="-1">Features it exercises <a class="header-anchor" href="#features-it-exercises" aria-label="Permalink to “Features it exercises”">​</a></h2><p>List view, cell spanning, column pinning, column resize, row pinning, row sort, slots, and theming.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to “Related pages”">​</a></h2><p><a href="/hafley-rxjs/signal-grid/view-list">List view and the transpose</a> for the state keys, <a href="/hafley-rxjs/signal-grid/cells-span">Span</a> for the span relation, and <a href="/hafley-rxjs/signal-grid/why-seats">The seat table</a> for why no stage branches on the orientation.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};